def bounded_counter(events, cap):
    value = 0
    for e in events:
        if e == "inc":
            value = min(cap, value + 1)
        elif e == "dec":
            value = max(0, value - 1)
        elif e == "reset":
            value = 0
    return value

def bank_balance_with_interest(events, rate):
    balance = 0
    for e in events:
        if e[0] == "deposit":
            balance += e[1]
        elif e[0] == "withdraw":
            if balance >= e[1]:
                balance -= e[1]
        elif e[0] == "month_end":
            balance = round(balance * (1 + rate), 2)
    return round(balance, 2)

def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door = "CLOSED"
    for c in commands:
        if c == "open":
            door = "OPEN"
        elif c == "close":
            door = "CLOSED"
        elif c == "up" and door == "CLOSED":
            floor = min(floor + 1, max_floor)
        elif c == "down" and door == "CLOSED":
            floor = max(floor - 1, min_floor)
    return (floor, door)

def traffic_light_emergency(events):
    cycle = ["RED", "GREEN", "YELLOW"]
    idx = 0
    for e in events:
        if e == "tick":
            idx = (idx + 1) % 3
        elif e == "emergency":
            idx = 0
    return cycle[idx]

def shopping_cart_total(events):
    cart = {}
    for event in events:
        if event[0] == "add":
            _, item, qty, price = event
            if item in cart:
                cart[item][0] += qty
                cart[item][1] = price
            else:
                cart[item] = [qty, price]
        elif event[0] == "remove":
            _, item, qty = event
            if item in cart:
                cart[item][0] -= qty
                if cart[item][0] <= 0:
                    del cart[item]
        elif event[0] == "clear":
            cart = {}
    total = sum(q * p for q, p in cart.values())
    return total

def turnstile_with_count(events):
    state = "LOCKED"
    passes = 0
    for e in events:
        if e == "coin":
            state = "UNLOCKED"
        elif e == "push":
            if state == "UNLOCKED":
                state = "LOCKED"
                passes += 1
    return (state, passes)

def robot_vacuum_cleaned(commands, obstacles):
    obstacles = set(obstacles)
    x, y = 0, 0
    facing = "N"
    visited = {(0, 0)}
    left_turn = {"N": "W", "W": "S", "S": "E", "E": "N"}
    right_turn = {"N": "E", "E": "S", "S": "W", "W": "N"}
    moves = {"N": (0, 1), "S": (0, -1), "E": (1, 0), "W": (-1, 0)}
    for c in commands:
        if c == "L":
            facing = left_turn[facing]
        elif c == "R":
            facing = right_turn[facing]
        elif c == "F":
            dx, dy = moves[facing]
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacles:
                x, y = nx, ny
                visited.add((x, y))
    return len(visited)

def parking_garage_fees(events, rate):
    parked = {}
    fees = {}
    for op, car_id, time in events:
        if op == "enter":
            if car_id not in parked:
                parked[car_id] = time
        elif op == "exit":
            if car_id in parked:
                fees[car_id] = (time - parked[car_id]) * rate
                del parked[car_id]
    return fees

def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    period = red_duration + green_duration
    result = []
    for a in arrivals:
        t = a
        while (t % period) >= red_duration:
            t += 1
        result.append(t)
    return result

def undo_redo_state(commands):
    state = []
    redo_stack = []
    for cmd in commands:
        if cmd[0] == "do":
            state.append(cmd[1])
            redo_stack = []
        elif cmd[0] == "undo":
            if state:
                redo_stack.append(state.pop())
        elif cmd[0] == "redo":
            if redo_stack:
                state.append(redo_stack.pop())
    return state

def vote_gate_state(events, threshold):
    net = 0
    gate = "CLOSED"
    for e in events:
        if gate == "OPEN":
            continue
        if e == "yes":
            net += 1
        elif e == "no":
            net -= 1
        if net >= threshold:
            gate = "OPEN"
    return gate

def coffee_machine_credit(events, prices, stock):
    stock = dict(stock)
    credit = 0
    dispensed = 0
    for op, val in events:
        if op == "insert":
            credit += val
        elif op == "select":
            drink = val
            if stock.get(drink, 0) > 0 and prices.get(drink, float("inf")) <= credit:
                credit -= prices[drink]
                stock[drink] -= 1
                dispensed += 1
    return (credit, stock, dispensed)

def bank_balance_with_fee(events, fee):
    balance = 0
    for op, amt in events:
        if op == "deposit":
            balance += amt
        elif op == "withdraw":
            if balance >= amt + fee:
                balance -= (amt + fee)
    return balance

def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    requests = set(requests)
    stops = []
    current = start_floor
    boundary = 1 if direction == -1 else top_floor
    while True:
        if current in requests:
            stops.append(current)
        if current == boundary:
            break
        current += direction
    return stops

def grid_bot_fuel(commands, fuel):
    x, y = 0, 0
    remaining = fuel
    moves = {"N": (0, 1), "S": (0, -1), "E": (1, 0), "W": (-1, 0)}
    for c in commands:
        if c in moves and remaining > 0:
            dx, dy = moves[c]
            x += dx
            y += dy
            remaining -= 1
    return ((x, y), remaining)

def register_finalized_totals(events):
    current = []
    totals = []
    for event in events:
        if event[0] == "scan":
            current.append(event[1])
        elif event[0] == "void":
            if current:
                current.pop()
        elif event[0] == "pay":
            totals.append(sum(current))
            current = []
    return totals

def light_switch_group(n, events):
    lights = [False] * n
    for event in events:
        if event[0] == "toggle":
            i = event[1]
            lights[i] = not lights[i]
        elif event[0] == "toggle_all":
            lights = [not l for l in lights]
        elif event[0] == "reset":
            lights = [False] * n
    return lights

def queue_with_capacity_serve(events, capacity):
    queue = []
    for event in events:
        if event[0] == "arrive":
            queue.append(event[1])
        elif event[0] == "serve":
            queue = queue[capacity:]
    return queue

def loan_debt_balance(events):
    debt = 0
    for op, amt in events:
        if op == "borrow":
            debt += amt
        elif op == "repay":
            debt -= min(amt, debt)
    return debt

def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def state_at(t, durations):
        red, green, yellow = durations
        cycle = red + green + yellow
        pos = t % cycle
        if pos < red:
            return "RED"
        elif pos < red + green:
            return "GREEN"
        else:
            return "YELLOW"
    count = 0
    for t in range(n_ticks):
        if state_at(t, durations_a) == "GREEN" and state_at(t, durations_b) == "GREEN":
            count += 1
    return count
